examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    MonarchAiContextChips(items, emptyText: {{empty}}) { id in
        items.removeAll { $0.id == id }
    }
    if items.count < initial.count {
        MonarchButton({{reset}}, variant: .ghost, size: .sm) { items = initial }
    }
}
.frame(maxWidth: 640)
.onAppear { items = initial }

examples.setupTemplate:
private let initial = [
        MonarchAiContextItem(
            id: {{items.0.id}},
            kind: .{{items.0.kind|raw}},
            label: {{items.0.label}},
            tokens: {{items.0.tokens}},
            isRemovable: {{items.0.removable}}
        ),
        MonarchAiContextItem(
            id: {{items.1.id}},
            kind: .{{items.1.kind|raw}},
            label: {{items.1.label}},
            tokens: {{items.1.tokens}},
            description: {{items.1.description}}
        ),
        MonarchAiContextItem(
            id: {{items.2.id}},
            kind: .{{items.2.kind|raw}},
            label: {{items.2.label}},
            tokens: {{items.2.tokens}}
        ),
        MonarchAiContextItem(
            id: {{items.3.id}},
            kind: .{{items.3.kind|raw}},
            label: {{items.3.label}},
            tokens: {{items.3.tokens}}
        ),
        MonarchAiContextItem(
            id: {{items.4.id}},
            kind: .{{items.4.kind|raw}},
            label: {{items.4.label}},
            tokens: {{items.4.tokens}}
        ),
]
@State private var items: [MonarchAiContextItem] = []

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    MonarchAiContextChips(items, emptyText: "Nothing attached. The assistant only sees your message.") { id in
        items.removeAll { $0.id == id }
    }
    if items.count < initial.count {
        MonarchButton("Reset", variant: .ghost, size: .sm) { items = initial }
    }
}
.frame(maxWidth: 640)
.onAppear { items = initial }
